update known_safe_harbors set evidence_summary = 'Exact coordinates (nearest gene: MAGI3, not MYBPC as previously thought). Validated in hESC: log2 fold-change between -0.067 and 0.065 vs. untargeted; 96 differentially expressed genes out of 29,696 tested; >98% Clover-positive cells maintained over 15 passages; stable expression in neuronal, hepatic, cardiac, and pancreatic derivatives; normal karyotype; teratoma confirms all 3 germ layers; nearest differentially expressed gene is >3Mb from the integration site.', stability = 'Stable for 15 passages and across 3-germ-layer differentiation' where source_pmid = '38164941' and evidence_summary = 'Coordenadas exatas (gene mais próximo: MAGI3, não MAGI3 nao MYBPC como pensado antes). Validado em hESC: log2 fold-change entre -0.067 e 0.065 vs. não-alvejadas; 96 genes diferencialmente expressos em 29.696 testados; >98% de células Clover-positivas mantidas ao longo de 15 passagens; expressão estável em derivados neuronais, hepáticos, cardíacos e pancreáticos; cariótipo normal; teratoma confirma as 3 camadas germinativas; gene diferencialmente expresso mais próximo fica a >3Mb do sítio de integração.';
