update known_safe_harbors set evidence_summary = 'Exact coordinates (nearest gene: TXNL1). Same validation profile as Pansio-1: log2-FC -0.067 to 0.065, 111 differentially expressed genes out of 29,696, >98% Clover-positive for 15 passages, expression maintained across all 3 germ layers, normal karyotype, nearest DE gene >5Mb away.', stability = 'Stable for 15 passages and across 3-germ-layer differentiation' where source_pmid = '38164941' and evidence_summary = 'Coordenadas exatas (gene mais próximo: TXNL1). Mesmo perfil de validação que Pansio-1: log2-FC -0.067 a 0.065, 111 genes diferencialmente expressos de 29.696, >98% Clover-positivas por 15 passagens, expressão mantida nas 3 camadas germinativas, cariótipo normal, gene DE mais próximo a >5Mb.';
