update known_safe_harbors set evidence_summary = 'Exact coordinates (nearest gene: ZNRF4). Same validation profile: log2-FC -0.067 to 0.065, 119 differentially expressed genes out of 29,696, >98% Clover-positive, expression maintained in derived neurons/hepatocytes/cardiomyocytes, normal karyotype. Nearest DE gene only ~1Mb away -- the closest of the three, still passed safety criteria.', stability = 'Stable across neuronal/hepatic/cardiac differentiation' where source_pmid = '38164941' and evidence_summary = 'Coordenadas exatas (gene mais próximo: ZNRF4). Mesmo perfil de validação: log2-FC -0.067 a 0.065, 119 genes diferencialmente expressos de 29.696, >98% Clover-positivas, expressão mantida em neurónios/hepatocitos/cardiomiócitos derivados, cariótipo normal. Gene DE mais próximo apenas a ~1Mb -- o mais próximo dos três, ainda assim aprovado nos critérios de segurança.';
