update known_safe_harbors set evidence_summary = 'Exact coordinates (intron of GOLGA4). The only one of 3 candidates tested in HUDEP2 erythroid cells to show full success: GFP signal remained positive for 3 months, with no significant change in GOLGA4 expression or in adjacent genes within the same TAD.', stability = 'Stable >3 months in erythroid cells' where source_pmid = '36131352' and evidence_summary = 'Coordenadas exatas (intrão de GOLGA4). Único dos 3 candidatos testados em células eritroides HUDEP2 a mostrar sucesso completo: sinal de GFP mantido positivo por 3 meses, sem alteração significativa na expressão de GOLGA4 nem de genes adjacentes no mesmo TAD.';
