update known_safe_harbors set locus_name = 'BLD_SHS14 / BLD_SHS15', evidence_summary = 'CORRECTION to a prior record (batch 2, via secondary review): these two candidates (ARID1B and TAF2) were indeed tested in HUDEP2 cells alongside BLD_SHS10, but the primary article states that "only BLD_GSH_10 showed full success" -- suggesting these two did NOT have the same positive result the secondary review implied. Confidence lowered to reflect this contradiction; needs direct confirmation against the primary article before any use.', stability = 'Contradicted by primary source -- needs direct confirmation' where source_pmid = '36131352' and evidence_summary = 'CORRECAO a registo anterior (lote 2, via review secundaria): esses dois candidatos (ARID1B e TAF2) foram de facto testados em células HUDEP2 juntamente com o BLD_SHS10, mas o artigo primário indica que "apenas BLD_GSH_10 mostrou sucesso completo" -- sugerindo que estes dois NAO tiveram o mesmo resultado positivo que a review secundária deu a entender. Confiança baixada para refletir esta contradição; precisa de confirmação direta contra o artigo primário antes de qualquer uso.';
update public_safe_harbors_staging set locus_name = 'BLD_SHS14 / BLD_SHS15', evidence_summary = 'CORRECTION to a prior record (batch 2, via secondary review): these two candidates (ARID1B and TAF2) were indeed tested in HUDEP2 cells alongside BLD_SHS10, but the primary article states that "only BLD_GSH_10 showed full success" -- suggesting these two did NOT have the same positive result the secondary review implied. Confidence lowered to reflect this contradiction; needs direct confirmation against the primary article before any use.', stability = 'Contradicted by primary source -- needs direct confirmation' where source_pmid = '36131352' and evidence_summary = 'CORRECAO a registo anterior (lote 2, via review secundaria): esses dois candidatos (ARID1B e TAF2) foram de facto testados em células HUDEP2 juntamente com o BLD_SHS10, mas o artigo primário indica que "apenas BLD_GSH_10 mostrou sucesso completo" -- sugerindo que estes dois NAO tiveram o mesmo resultado positivo que a review secundária deu a entender. Confiança baixada para refletir esta contradição; precisa de confirmação direta contra o artigo primário antes de qualquer uso.';

update known_safe_harbors set evidence_summary = 'Rich validation (exact location only in a figure, not extractable from text): stable mRuby expression 90 days after integration in HEK293T, outperforming AAVS1 in the same assay. 94.7% mRuby+ primary T cells after selection; >92% GFP+ primary dermal fibroblasts, maintained >25 days. Single-cell RNA-seq shows minimal transcriptome disruption, no upregulation of cancer-associated pathways.', stability = 'Stable >90 days in cell lines; >25 days in fibroblasts' where source_pmid = '35474867' and evidence_summary = 'Validação rica (localização exata só em figura, não extraível em texto): expressão estável de mRuby 90 dias após integração em HEK293T, superando o desempenho do AAVS1 no mesmo ensaio. 94.7% de células T primárias mRuby+ após selecção; >92% de fibroblastos dérmicos primários GFP+, mantido por >25 dias. RNA-seq de célula única mostra disrupção mínima do transcriptoma, sem sobre-regulação de vias associadas a cancro.';
update public_safe_harbors_staging set evidence_summary = 'Rich validation (exact location only in a figure, not extractable from text): stable mRuby expression 90 days after integration in HEK293T, outperforming AAVS1 in the same assay. 94.7% mRuby+ primary T cells after selection; >92% GFP+ primary dermal fibroblasts, maintained >25 days. Single-cell RNA-seq shows minimal transcriptome disruption, no upregulation of cancer-associated pathways.', stability = 'Stable >90 days in cell lines; >25 days in fibroblasts' where source_pmid = '35474867' and evidence_summary = 'Validação rica (localização exata só em figura, não extraível em texto): expressão estável de mRuby 90 dias após integração em HEK293T, superando o desempenho do AAVS1 no mesmo ensaio. 94.7% de células T primárias mRuby+ após selecção; >92% de fibroblastos dérmicos primários GFP+, mantido por >25 dias. RNA-seq de célula única mostra disrupção mínima do transcriptoma, sem sobre-regulação de vias associadas a cancro.';

update known_safe_harbors set evidence_summary = 'Rich validation: stable mRuby expression 90 days in HEK293T AND Jurkat, outperforming the CCR5 locus in Jurkat. 91.8% mRuby+ primary T cells after selection; >92% GFP+ fibroblasts, maintained >25 days. Bulk RNA-seq showed no significant enrichment of cancer-associated genes or pathways.', stability = 'Stable >90 days in cell lines; >25 days in fibroblasts' where source_pmid = '35474867' and evidence_summary = 'Validação rica: expressão estável de mRuby 90 dias em HEK293T E em Jurkat, superando o desempenho do locus CCR5 em Jurkat. 91.8% de células T primárias mRuby+ após selecção; >92% de fibroblastos GFP+, mantido >25 dias. RNA-seq em massa sem enriquecimento significativo de genes ou vias associadas a cancro.';
update public_safe_harbors_staging set evidence_summary = 'Rich validation: stable mRuby expression 90 days in HEK293T AND Jurkat, outperforming the CCR5 locus in Jurkat. 91.8% mRuby+ primary T cells after selection; >92% GFP+ fibroblasts, maintained >25 days. Bulk RNA-seq showed no significant enrichment of cancer-associated genes or pathways.', stability = 'Stable >90 days in cell lines; >25 days in fibroblasts' where source_pmid = '35474867' and evidence_summary = 'Validação rica: expressão estável de mRuby 90 dias em HEK293T E em Jurkat, superando o desempenho do locus CCR5 em Jurkat. 91.8% de células T primárias mRuby+ após selecção; >92% de fibroblastos GFP+, mantido >25 dias. RNA-seq em massa sem enriquecimento significativo de genes ou vias associadas a cancro.';

